import{_ as t,o as d,c as e,a2 as l}from"./chunks/framework.BUwdTBzS.js";const h=JSON.parse('{"title":"tech-doc","description":"文档处理中心。统一管理开发日志（devlog）、文档同步（doc-sync）和技术方案文档（tech-proposal）三大功能模块。支持独立使用和被 dev-flow 按需调用。根据用户意图自动路由到对应模块，按需加载避免 Token 浪费。技术方案模块同时支持在线发布（需配置 doc_platf…","frontmatter":{"title":"tech-doc","description":"文档处理中心。统一管理开发日志（devlog）、文档同步（doc-sync）和技术方案文档（tech-proposal）三大功能模块。支持独立使用和被 dev-flow 按需调用。根据用户意图自动路由到对应模块，按需加载避免 Token 浪费。技术方案模块同时支持在线发布（需配置 doc_platf…"},"headers":[],"relativePath":"skills/tech-doc.md","filePath":"skills/tech-doc.md","lastUpdated":null}'),a={name:"skills/tech-doc.md"};function c(s,o,n,r,i,p){return d(),e("div",null,[...o[0]||(o[0]=[l(`<blockquote><p>📄 本页由源文件 <code>skills/tech-doc/SKILL.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="tech-doc" tabindex="-1">tech-doc <a class="header-anchor" href="#tech-doc" aria-label="Permalink to &quot;tech-doc&quot;">​</a></h1><blockquote><p>统一的文档处理入口。支持三大功能模块，根据场景按需加载对应模块。 可独立使用（用户触发文档相关操作），也被 dev-flow 按步骤调用。</p></blockquote><hr><h2 id="功能路由" tabindex="-1">功能路由 <a class="header-anchor" href="#功能路由" aria-label="Permalink to &quot;功能路由&quot;">​</a></h2><p>识别用户意图后，<strong>只加载对应模块</strong>，避免一次性加载全部内容浪费 Token。</p><blockquote><p>📌 <strong>触发关键词的单一权威源</strong>：完整的触发关键词清单（含显式/隐式/不触发场景、组合调用、dev-flow 调用映射）维护在 <code>config/triggers.yaml</code>。下表仅作为路由速查；当 <code>config/triggers.yaml</code> 与本表冲突时以前者为准。</p></blockquote><table tabindex="0"><thead><tr><th>模块</th><th>文件</th><th>触发关键词（速查）</th></tr></thead><tbody><tr><td><strong>开发日志</strong></td><td><code>modules/devlog.md</code>（~15KB）</td><td>&quot;生成开发日志&quot;/&quot;记录改动&quot;/&quot;生成 devlog&quot;/&quot;写个开发记录&quot;</td></tr><tr><td><strong>文档同步</strong></td><td><code>modules/doc-sync.md</code>（~13KB）</td><td>&quot;同步文档&quot;/&quot;更新技术方案&quot;/&quot;文档更新了&quot;/&quot;doc_platform 同步&quot;/&quot;文档改了&quot;/&quot;设计稿更新&quot;/&quot;需求变更&quot;/&quot;接口改了&quot;</td></tr><tr><td><strong>技术方案</strong></td><td><code>modules/doc-platform-doc.md</code>（~44KB）</td><td>&quot;技术方案&quot;/&quot;技术分享&quot;/&quot;发布文档&quot;/&quot;写/生成+文档类型&quot;</td></tr></tbody></table><blockquote><p>📌 本地模式详细说明 → <code>references/local-doc-mode.md</code>，类似 devlog 目录的零配置体验</p></blockquote><h3 id="技术方案文档支持范围" tabindex="-1">技术方案文档支持范围 <a class="header-anchor" href="#技术方案文档支持范围" aria-label="Permalink to &quot;技术方案文档支持范围&quot;">​</a></h3><blockquote><p>📌 <strong>输出模式</strong>：本模块支持两种输出模式，由 <code>config/org.yaml</code> 的 <code>tech_docs_mode</code> + <code>doc_platform_url</code> 联合控制：</p><ul><li><strong>本地模式</strong>（默认，零配置）：文档保存到 <code>~/.codebuddy/tech-docs/</code> 目录（类似 devlog）</li><li><strong>在线模式</strong>（需配置）：文档通过 MCP 工具发布到配置的文档平台</li></ul><p>两种模式下文档模板、lint 校验、工作流程一致，仅&quot;最终保存位置&quot;不同。 详细模式说明 → <code>references/local-doc-mode.md</code></p></blockquote><p><code>doc-platform-doc</code> 模块支持三种文档类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>模板状态</th><th>说明</th></tr></thead><tbody><tr><td><strong>tech-proposal</strong>（技术方案）</td><td>✅ 完整模板</td><td>九章节 + 附录，含完整变量填充规范、流程图判断节点规范等</td></tr><tr><td><strong>tech-sharing</strong>（技术分享）</td><td>✅ 完整模板（B2-D2 改造）</td><td>标准章节：背景/核心要点/实践方案/踩坑总结/总结与展望</td></tr><tr><td><strong>release-doc</strong>（发布文档）</td><td>✅ 完整模板（B2-D3 改造）</td><td>标准章节：版本信息/新增功能/修复问题/已知问题/升级说明</td></tr></tbody></table><blockquote><p>📌 LLM 在生成对应类型文档时<strong>必须严格加载并使用 <code>doc-platform-doc.md</code> 中对应模板</strong>，禁止自由发挥（参见 <code>~/.codebuddy/rules/AI行为规范.mdc</code> §「Skill 模板严格遵循规则」）。</p></blockquote><h3 id="加载方式" tabindex="-1">加载方式 <a class="header-anchor" href="#加载方式" aria-label="Permalink to &quot;加载方式&quot;">​</a></h3><p>识别意图后，使用 <code>read_file</code> 加载对应模块文件（相对于本 Skill 目录）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 示例：用户说“生成开发日志”</span></span>
<span class="line"><span>read_file(&quot;modules/devlog.md&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 示例：用户说“同步文档”</span></span>
<span class="line"><span>read_file(&quot;modules/doc-sync.md&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 示例：用户说“写个技术方案”</span></span>
<span class="line"><span>read_file(&quot;modules/doc-platform-doc.md&quot;)</span></span></code></pre></div><h3 id="路由判断规则" tabindex="-1">路由判断规则 <a class="header-anchor" href="#路由判断规则" aria-label="Permalink to &quot;路由判断规则&quot;">​</a></h3><ol><li><strong>优先匹配显式关键词</strong>：用户消息中包含上表关键词 → 直接路由到对应模块</li><li><strong>组合场景</strong>：某些操作需要同时加载多个模块（如 doc-sync 执行过程中可能需要更新 devlog），由子模块内部说明依赖关系</li><li><strong>不确定时询问</strong>：无法判断用户意图时，展示三个模块选项让用户选择</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你想执行哪种文档操作？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 📝 **开发日志** —— 生成 devlog.md 和 plan.md（本地开发记录）</span></span>
<span class="line"><span>2. 🔄 **文档同步** —— 同步工作上下文、开发日志和 技术方案文档</span></span>
<span class="line"><span>3. 📋 **文档平台 文档** —— 生成/更新 技术方案文档、技术分享或发布文档</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请选择（1/2/3）或直接描述你的需求。</span></span></code></pre></div><hr><h2 id="dev-flow-场景路由" tabindex="-1">dev-flow 场景路由 <a class="header-anchor" href="#dev-flow-场景路由" aria-label="Permalink to &quot;dev-flow 场景路由&quot;">​</a></h2><blockquote><p>🔗 <strong>单一权威源</strong>：dev-flow 调用映射同时也维护在 <code>config/triggers.yaml</code> 的 <code>&lt;模块&gt;.dev_flow_invocation</code> 节点（<code>devlog</code> / <code>doc_sync</code> / <code>doc_platform_doc</code> 三个模块各自一份）。下表为跨模块综合表格，方便完整查看。增删调用点请同时修改 yaml 与本表。</p></blockquote><p>dev-flow 各步骤调用 <code>use_skill(&#39;tech-doc&#39;)</code> 后，根据以下映射加载对应模块：</p><table tabindex="0"><thead><tr><th>dev-flow 步骤</th><th>加载模块</th><th>说明</th></tr></thead><tbody><tr><td>步骤 4 阶段 3 决策后</td><td><code>modules/doc-platform-doc.md</code></td><td><code>action ∈ {create, update}</code> 时加载。在线模式直接发布；本地模式保存到 <code>tech-docs/</code> 目录</td></tr><tr><td>步骤 5.5b 编码后</td><td><code>modules/doc-sync.md</code></td><td>文档同步时机 ①（最轻量）</td></tr><tr><td>步骤 5.5b 接口变更例外</td><td><code>modules/doc-sync.md</code> + <code>modules/doc-platform-doc.md</code></td><td>protobuf/接口变更时，时机 ① 提升为时机 ②</td></tr><tr><td>步骤 6 前验证前</td><td><code>modules/doc-sync.md</code></td><td>文档同步时机 ②（主要同步点）</td></tr><tr><td>步骤 7 H.3+</td><td><code>modules/doc-platform-doc.md</code> 模式 C</td><td>上线后 bugfix 或提测后迭代修复命中阈值时。在线模式同步到知识库；本地模式对比本地文件</td></tr><tr><td>步骤 7 / 收尾 3.5</td><td><code>modules/devlog.md</code> + <code>modules/doc-sync.md</code></td><td>生成开发日志 + 文档同步兜底</td></tr><tr><td><strong>步骤 10.3.5 归档同步</strong></td><td><code>modules/doc-platform-doc.md</code> 模式 C</td><td><strong>完整执行必走</strong>。在线模式：<code>doc_platform_tech_proposal.action ∉ {skip, auto_inherited_skip}</code> 时强制同步到知识库。本地模式：将文档写入 <code>tech-docs/</code> 目录归档</td></tr><tr><td>步骤 10 归档三件套</td><td><code>modules/devlog.md</code> + <code>modules/doc-sync.md</code></td><td>devlog + 工作上下文完整归档</td></tr><tr><td>被动同步（外部文档变更）</td><td><code>modules/doc-sync.md</code></td><td>用户告知文档变更时</td></tr></tbody></table><p><strong>dev-flow 调用约定</strong>：</p><ul><li>dev-flow 各步骤说明中会标注需要加载的具体模块，按标注加载即可</li><li>同一步骤需要多个模块时，按顺序依次加载</li><li>模块加载后按其内部规则执行，无需回到本入口文件</li></ul><hr><h2 id="独立使用-用户调用指南" tabindex="-1">独立使用（用户调用指南） <a class="header-anchor" href="#独立使用-用户调用指南" aria-label="Permalink to &quot;独立使用（用户调用指南）&quot;">​</a></h2><p>tech-doc 既可以被 dev-flow 自动调用，也可以<strong>脱离 dev-flow 独立使用</strong>。以下是用户的具体调用方式。</p><h3 id="调用方式" tabindex="-1">调用方式 <a class="header-anchor" href="#调用方式" aria-label="Permalink to &quot;调用方式&quot;">​</a></h3><p><strong>统一入口</strong>：对 AI 说任何文档相关的需求即可，AI 会自动触发 <code>use_skill(&#39;tech-doc&#39;)</code> 并路由到对应模块。</p><p><strong>无需记忆模块名</strong>——只需用自然语言描述需求，AI 根据关键词自动匹配。</p><h3 id="📝-开发日志-devlog-模块" tabindex="-1">📝 开发日志（devlog 模块） <a class="header-anchor" href="#📝-开发日志-devlog-模块" aria-label="Permalink to &quot;📝 开发日志（devlog 模块）&quot;">​</a></h3><p>生成本地开发日志 <code>devlog.md</code> 和执行计划 <code>plan.md</code>。</p><p><strong>调用示例</strong>：</p><ul><li>&quot;帮我生成开发日志&quot;</li><li>&quot;记录一下这次改动&quot;</li><li>&quot;生成 devlog&quot;</li><li>&quot;写个开发记录&quot;</li></ul><p><strong>输出</strong>：<code>~/.codebuddy/dev-logs/&lt;项目名&gt;/&lt;分支名&gt;/devlog.md</code> + <code>plan.md</code></p><h3 id="🔄-文档同步-doc-sync-模块" tabindex="-1">🔄 文档同步（doc-sync 模块） <a class="header-anchor" href="#🔄-文档同步-doc-sync-模块" aria-label="Permalink to &quot;🔄 文档同步（doc-sync 模块）&quot;">​</a></h3><p>协调管理工作上下文、开发日志和 技术方案文档三类文档的一致性。</p><p><strong>调用示例</strong>：</p><ul><li>&quot;同步一下文档&quot;</li><li>&quot;doc_platform 同步&quot;</li><li>&quot;文档更新了，帮我同步&quot;</li><li>&quot;需求/设计稿/接口改了&quot;</li></ul><p><strong>核心能力</strong>：检查三类文档是否一致，按时机由轻到重递进同步（更新进度 → 三件套同步 → 兜底检查 → 完整同步）。</p><h3 id="📋-文档平台-文档-doc-platform-doc-模块" tabindex="-1">📋 文档平台 文档（doc-platform-doc 模块） <a class="header-anchor" href="#📋-文档平台-文档-doc-platform-doc-模块" aria-label="Permalink to &quot;📋 文档平台 文档（doc-platform-doc 模块）&quot;">​</a></h3><p>生成/编辑/发布 文档平台 线上技术文档，支持三种文档类型。</p><p><strong>调用示例</strong>：</p><ul><li>&quot;写个技术方案&quot; / &quot;生成技术方案&quot;</li><li>&quot;帮我写个技术分享&quot;</li><li>&quot;生成发布文档&quot; / &quot;写个 release notes&quot;</li><li>&quot;精简这个 doc_platform 文档&quot; + 文档平台 链接</li><li>&quot;优化一下这个文档&quot; + 文档平台 链接</li><li>&quot;把这个方案发到 doc_platform&quot;</li></ul><p><strong>三种工作模式</strong>：</p><ul><li><strong>模式 A（自动填充）</strong>：从工作上下文/代码自动提取信息生成文档</li><li><strong>模式 B（手动输入）</strong>：用户提供素材，AI 组织生成文档</li><li><strong>模式 C（编辑优化）</strong>：对已有 文档平台 文档进行精简/优化/补充。<strong>默认使用方案 B（建议模式）</strong>——输出优化建议供用户自行更新；用户明确要求时切换为方案 A（AI 直接更新 文档平台）</li></ul><h3 id="组合调用" tabindex="-1">组合调用 <a class="header-anchor" href="#组合调用" aria-label="Permalink to &quot;组合调用&quot;">​</a></h3><blockquote><p>🔗 <strong>单一权威源</strong>：组合调用场景同时维护在 <code>config/triggers.yaml</code> 的 <code>combo_scenarios</code> 节点。下表仅为高频示例；增删场景请同时修改 yaml 与本表。</p></blockquote><p>某些场景需要多个模块协同：</p><table tabindex="0"><thead><tr><th>场景</th><th>说话方式</th><th>实际加载</th></tr></thead><tbody><tr><td>开发完想一次性搞定</td><td>&quot;帮我生成开发日志，顺便同步文档&quot;</td><td>devlog + doc-sync</td></tr><tr><td>需求完结全量归档</td><td>&quot;全部文档归档一下&quot;</td><td>devlog + doc-sync + doc-platform-doc</td></tr><tr><td>写完方案想同步</td><td>&quot;技术方案写好了，帮我同步&quot;</td><td>doc-sync</td></tr></tbody></table>`,53)])])}const g=t(a,[["render",c]]);export{h as __pageData,g as default};
